def valuation_closure(v, S, universe):
    threshold = max((v(x) for x in S), default=0)
    return frozenset(x for x in universe if v(x) <= threshold)

def normalize_valuation(v, universe):
    counts = {}
    for x in universe:
        counts[x] = sum(1 for y in universe if v(y) < v(x))
    return lambda x: counts[x]

def is_chain(sets):
    for i, s in enumerate(sets):
        for t in sets[i+1:]:
            if not (s <= t or t <= s):
                return False
    return True
